        int u, v;
        scanf("%d %d", &u, &v);
        --u;
        --v;

        for (int i = 0; i + 1 < L; ++i) {
            int u1 = u + i * n;
            int v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n;
            int v2 = v + i * n;

            for (int j = 0; j < k; ++j) {
                int w = c + d * (2 * j + 1);
                mcmf.addEdge(u1, v1, 1, w);
                mcmf.addEdge(v2, u2, 1, w);
            }
        }
    }

    for (int i = 0; i + 1 < L; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n;
            int v = j + (i + 1) * n;
            mcmf.addEdge(u, v, INF, c);
