import java.io.*;
import java.util.*;

class MinCostFlow {
    static final int INF = Integer.MAX_VALUE;
    static final int MAXN = 10001;

    class Edge {
        int to, rev, cap, cost;
        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    ArrayList<ArrayList<Edge>> adj;
    int nodes;
    int[] dist, potential, levelArr, iterArr;
    boolean[] done;

    MinCostFlow() {
        adj = new ArrayList<>();
        nodes = 0;
        potential = new int[MAXN];
        Arrays.fill(potential, 0);
    }

    int addNodes(int cnt) {
        while (cnt-- > 0) {
            adj.add(new ArrayList<>());
            nodes++;
        }
        return nodes - 1;
    }

    void addEdge(int u, int v, int cap, int cost) {
        adj.get(u).add(new Edge(v, adj.get(v).size(), cap, cost));
        adj.get(v).add(new Edge(u, adj.get(u).size() - 1, 0, -cost));
    }

    boolean dijkstra(int s, int t) {
        dist = new int[nodes];
        done = new boolean[nodes];
        Arrays.fill(dist, INF);
        Arrays.fill(done, false);
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        dist[s] = 0;
        pq.offer(new int[]{0, s});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int du = cur[0], u = cur[1];
            if (done[u]) continue;
            done[u] = true;

            for (Edge e : adj.get(u)) {
                int v = e.to;
                if (e.cap == 0 || done[v]) continue;
                int nd = du + potential[u] + e.cost - potential[v];
                if (dist[v] > nd) {
                    dist[v] = nd;
                    pq.offer(new int[]{nd, v});
                }
            }
        }
        return done[t];
    }

    boolean buildLevelGraph(int s, int t) {
        levelArr = new int[nodes];
        Arrays.fill(levelArr, 0);
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        levelArr[s] = 1;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (Edge e : adj.get(u)) {
                int v = e.to;
                if (e.cap == 0 || levelArr[v] != 0) continue;
                if (dist[v] == dist[u] + e.cost - potential[v] + potential[u]) {
                    levelArr[v] = levelArr[u] + 1;
                    q.offer(v);
                }
            }
        }
        return levelArr[t] != 0;
    }

    int dfs(int u, int t, int f) {
        if (u == t) return f;
        int sent = 0;

        for (int i = iterArr[u]; i < adj.get(u).size(); i++) {
            Edge e = adj.get(u).get(i);
            int v = e.to;
            if (e.cap == 0 || levelArr[v] != levelArr[u] + 1) continue;
            if (dist[v] != dist[u] + e.cost - potential[v] + potential[u]) continue;

            int ret = dfs(v, t, Math.min(f, e.cap));
            if (ret > 0) {
                sent += ret;
                f -= ret;
                e.cap -= ret;
                adj.get(v).get(e.rev).cap += ret;
                if (f == 0) break;
            }
            iterArr[u] = i + 1; // update iterator
        }
        return sent;
    }

    int[] minCostFlow(int s, int t, int maxFlow) {
        int flow = 0, cost = 0;
        Arrays.fill(potential, 0, nodes, 0);

        while (dijkstra(s, t)) {
            int phaseFlow = 0;

            while (buildLevelGraph(s, t)) {
                iterArr = new int[nodes];
                Arrays.fill(iterArr, 0);
                int df = dfs(s, t, maxFlow);
                maxFlow -= df;
                phaseFlow += df;
                if (maxFlow == 0) break;
            }

            flow += phaseFlow;
            cost += (dist[t] + potential[t]) * phaseFlow;

            for (int i = 0; i < nodes; i++) {
                if (dist[i] != INF) potential[i] += dist[i];
            }

            if (maxFlow == 0) break;
        }

        return new int[]{flow, cost};
    }
}

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        MinCostFlow mcmf = new MinCostFlow();
        int L = Math.max(n, k) * 2;

        mcmf.addNodes(L * n);
        int s = mcmf.addNodes(1);
        int t = mcmf.addNodes(1);

        st = new StringTokenizer(br.readLine());
        for (int j = 0; j < k; j++) {
            int a = Integer.parseInt(st.nextToken()) - 1;
            mcmf.addEdge(s, a, 1, 0);
        }

        for (int z = 0; z < m; z++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;

            for (int i = 0; i + 1 < L; i++) {
                int u1 = u + i * n;
                int v1 = v + (i + 1) * n;
                int u2 = u + (i + 1) * n;
                int v2 = v + i * n;

                for (int j = 0; j < k; j++) {
                    int w = c + d * (2 * j + 1);
                    mcmf.addEdge(u1, v1, 1, w);
                    mcmf.addEdge(v2, u2, 1, w);
                }
            }
        }

        for (int i = 0; i + 1 < L; i++) {
            for (int j = 0; j < n; j++) {
                int u = j + i * n;
                int v = j + (i + 1) * n;
                mcmf.addEdge(u, v, MinCostFlow.INF, c);
            }
        }

        for (int i = 0; i < L; i++) {
            mcmf.addEdge(i * n, t, MinCostFlow.INF, 0);
        }

        int[] result = mcmf.minCostFlow(s, t, MinCostFlow.INF);
        System.out.println(result[1]);
    }
}
